/**
 * Fixture for the facet-quality gate (spec 956, T011), rebuilt from real
 * pre-production traffic to the Ananda Europe workspace ("Claudio EN" / "Claudio
 * IT" website-embed agents; yoga, meditation, Kriya Yoga, retreats).
 *
 * Provenance: harvested via `GET /api/v1/history` against the live pre-prod API
 * (152 history entries; 150 were chat conversations, 2 were unrelated search-log
 * entries), then every visitor/user-role message across all 150 conversation
 * details was collected (458 messages), filtered to length 15-300 characters,
 * deduped (case/whitespace-normalized exact duplicates, then a small number of
 * same-language/same-intent trivial near-duplicates), and scanned for PII by an
 * LLM pass plus a human review of every flag (emails, phone numbers, personal
 * names used as the subject of a personal situation, postal addresses, booking
 * references, and other identifying detail were dropped; the organization's own
 * public teachers/lineage figures were kept, matching the "who is Narayani" carve
 * -out). `topic` and `crossLingualGroup` were assigned by gpt-5.2 from the
 * question text ALONE — the labeller never saw a facet, so labels are not biased
 * toward the facet representation. The taxonomy this was labelled against is
 * committed alongside this file in `taxonomy.json`.
 *
 * `crossLingualGroup` here marks intents that occurred, unprompted, in two or
 * more languages in real traffic — found by grouping same-intent labels across
 * languages, not authored by hand. Real traffic yields far fewer such groups than
 * the hand-authored predecessor of this fixture did, and skews heavily towards
 * English and Italian (this workspace runs one English and one Italian embed
 * agent); see the recording PR description for the exact language breakdown.
 *
 * `topic: null` marks a real outlier: either a message the taxonomy pass judged
 * did not fit any topic well, or genuine adversarial/off-topic/fragment traffic.
 * Outliers are clustered along with everything else, matching real conditions,
 * but excluded from the scored partition.
 */

export type FacetQualityTopic =
  | "retreats_courses_calendar_booking"
  | "kriya_yoga_initiation_path"
  | "meditation_guidance_live_sessions"
  | "yoga_practice_videos_routines"
  | "locations_local_groups_sangha"
  | "volunteering_seva_work_exchange_jobs"
  | "travel_pilgrimages_assisi_logistics"
  | "online_courses_platform_access_payments"
  | "community_media_newsletter_social"
  | "teachings_philosophy_spiritual_questions"
  | "people_lineage_and_controversies"
  | "wellness_products_sprays";

export type FacetQualityLanguage = "en" | "es" | "it" | "ru";

export interface FacetQualityQuestion {
  id: string;
  language: FacetQualityLanguage;
  question: string;
  /** Hand-... erm, LLM-assigned reference topic from question text alone; `null` marks a real outlier. */
  topic: FacetQualityTopic | null;
  /** Same intent occurring in more than one language in real traffic. Defines the multilingual subset. */
  crossLingualGroup?: string;
}

